DECLARE @ci SYSNAME = '@{item().capture_instance}';
DECLARE @desde BINARY(10) = CASE WHEN '@{item().last_lsn}' = '' THEN sys.fn_cdc_get_min_lsn(@ci) ELSE sys.fn_cdc_increment_lsn(CONVERT(BINARY(10), '@{item().last_lsn}', 1)) END;
DECLARE @hasta BINARY(10) = sys.fn_cdc_get_max_lsn();
SELECT CONVERT(VARCHAR(34), @desde, 1) AS lsn_desde,
       CONVERT(VARCHAR(34), @hasta, 1) AS lsn_hasta,
       CASE WHEN @desde IS NULL OR @hasta IS NULL OR @desde > @hasta THEN 0 ELSE 1 END AS hay_cambios;

DECLARE @desde BINARY(10) = CONVERT(BINARY(10), '@{activity('ResolverRangoLSN').output.firstRow.lsn_desde}', 1);
DECLARE @hasta BINARY(10) = CONVERT(BINARY(10), '@{activity('ResolverRangoLSN').output.firstRow.lsn_hasta}', 1);
SELECT *, SYSUTCDATETIME() AS ingested_at
FROM cdc.fn_cdc_get_all_changes_@{item().capture_instance}(@desde, @hasta, N'all update old');
